*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-secondary: #4A4A4A;
  --text-muted: #7A7A7A;
  --border: #D4CBC0;
  --terracotta: #C4755B;
  --sage: #8B9E7E;
  --sand: #D4C5A9;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --page-padding: clamp(1.5rem, 4vw, 5rem);
  --max-width: 1320px;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.65;
  font-size: 1.0625rem;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

body.menu-open {
  overflow: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img { max-width: 100%; display: block; }

/* ===== HEADER & NAV ===== */

.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem var(--page-padding);
  background-color: var(--bg);
  transition: background-color 0.3s ease;
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: var(--max-width);
  margin: 0 auto;
}

.nav-logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  cursor: pointer;
}

.nav-links {
  display: flex;
  gap: 2.5rem;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 400;
  letter-spacing: 0.01em;
  position: relative;
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.nav-links a:hover {
  opacity: 0.55;
}

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 44px;
  height: 44px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 210;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background-color: var(--text);
  transition: transform 0.3s ease, opacity 0.3s ease;
}

.hamburger.is-active span:nth-child(1) {
  transform: translateY(6.5px) rotate(45deg);
}

.hamburger.is-active span:nth-child(2) {
  opacity: 0;
}

.hamburger.is-active span:nth-child(3) {
  transform: translateY(-6.5px) rotate(-45deg);
}

/* ===== MOBILE MENU ===== */

.mobile-menu {
  position: fixed;
  inset: 0;
  z-index: 200;
  background-color: var(--bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2.5rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.mobile-menu.is-open {
  opacity: 1;
  pointer-events: all;
}

.mobile-menu a {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 6vw, 3.5rem);
  font-weight: 500;
  letter-spacing: -0.02em;
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.mobile-menu a:hover {
  opacity: 0.55;
}

/* ===== HERO ===== */

.hero {
  min-height: 70vh;
  display: flex;
  align-items: flex-end;
  padding: 0 var(--page-padding);
  padding-top: 10rem;
  padding-bottom: 4rem;
}

.hero-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  width: 100%;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.8rem, 7vw, 5.5rem);
  font-weight: 600;
  line-height: 1.08;
  letter-spacing: -0.03em;
  max-width: 14ch;
}

/* ===== MEDIA SHOWCASE ===== */

.media-showcase {
  padding: 2rem var(--page-padding) 4rem;
}

.media-showcase-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr 1fr;
  gap: 0.75rem;
  height: clamp(280px, 50vw, 560px);
}

.media-block {
  border-radius: 4px;
}

.media-block--terracotta { background-color: var(--terracotta); }
.media-block--sage { background-color: var(--sage); }
.media-block--sand { background-color: var(--sand); }

/* ===== CLIENT MARQUEE ===== */

.client-marquee {
  padding: 4rem 0;
  overflow: hidden;
}

.marquee-row {
  overflow: hidden;
  white-space: nowrap;
  padding: 0.6rem 0;
}

.marquee-track {
  display: inline-flex;
  align-items: center;
  will-change: transform;
}

.marquee-track--left {
  animation: marquee-left 45s linear infinite;
}

.marquee-track--right {
  animation: marquee-right 45s linear infinite;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 3.5vw, 3rem);
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--text);
  padding: 0 1rem;
  display: inline-flex;
  align-items: center;
  gap: 2rem;
  flex-shrink: 0;
}

.marquee-separator {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--border);
  margin: 0 1.25rem;
  flex-shrink: 0;
}

@media (prefers-reduced-motion: reduce) {
  .marquee-track--left,
  .marquee-track--right {
    animation: none;
  }
}

/* ===== ABOUT ===== */

.about {
  padding: 6rem var(--page-padding) 8rem;
}

.about-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 4rem;
}

.about-label {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding-top: 0.5rem;
}

.about-text p {
  font-size: 1.125rem;
  line-height: 1.75;
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
  max-width: 680px;
}

.about-text p:last-child {
  margin-bottom: 0;
}

/* ===== FOUNDER LETTER (neweno.html) ===== */

.founder-letter {
  padding: 12rem var(--page-padding) 8rem;
  display: flex;
  justify-content: center;
}

.founder-letter-inner {
  max-width: 660px;
  width: 100%;
}

.founder-letter-inner h1 {
  font-family: var(--font-serif);
  font-size: clamp(2.2rem, 5vw, 3.5rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 4rem;
}

.founder-letter-inner p {
  font-size: 1.125rem;
  line-height: 1.85;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}

.founder-letter-inner p:last-child {
  margin-bottom: 0;
}

.founder-letter-inner p:first-of-type::first-letter {
  font-family: var(--font-serif);
  font-size: 3.8rem;
  font-weight: 600;
  float: left;
  line-height: 0.8;
  margin-right: 0.15em;
  margin-top: 0.1em;
  color: var(--text);
}

.founder-signature {
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
}

.founder-signature p {
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 1.25rem;
  color: var(--text);
}

/* ===== SERVICES ===== */

.philosophy {
  padding: 12rem var(--page-padding) 5rem;
}

.philosophy-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.philosophy-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: 3rem;
}

.philosophy-text {
  max-width: 680px;
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--text-secondary);
}

.philosophy-text p {
  margin-bottom: 1.5rem;
}

.section-divider {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--page-padding);
}

.section-divider hr {
  border: none;
  border-top: 1px solid var(--border);
}

.service-details {
  padding: 5rem var(--page-padding) 8rem;
}

.service-details-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.service-details-heading {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 4rem;
  max-width: 18ch;
  font-style: italic;
}

.service-item {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 3rem;
  margin-bottom: 3.5rem;
  padding-bottom: 3.5rem;
  border-bottom: 1px solid var(--border);
}

.service-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}

.service-name {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  padding-top: 0.25rem;
}

.service-description {
  font-size: 1.0625rem;
  line-height: 1.8;
  color: var(--text-secondary);
  max-width: 640px;
}

/* ===== CLIENTS ===== */

.clients-heading {
  padding: 12rem var(--page-padding) 4rem;
}

.clients-heading-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-heading h1 {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.clients-heading h1 span {
  font-weight: 400;
  font-style: italic;
  color: var(--text-muted);
  margin-left: 0.15em;
}

.clients-section {
  padding: 0 var(--page-padding) 8rem;
}

.clients-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2.5rem;
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: 0.65rem;
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-muted);
}

/* ===== CONTACT ===== */

.contact-hero {
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10rem var(--page-padding) 2rem;
  text-align: center;
}

.contact-title {
  font-family: var(--font-serif);
  font-size: clamp(5rem, 18vw, 16rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.04em;
}

.contact-links {
  display: flex;
  justify-content: center;
  gap: 3rem;
  padding: 0 var(--page-padding) 8rem;
}

.contact-links a {
  font-size: 1.0625rem;
  font-weight: 400;
  color: var(--text-secondary);
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.contact-links a:hover {
  opacity: 0.55;
}

/* ===== FOOTER ===== */

.footer {
  padding: 3rem var(--page-padding);
  border-top: 1px solid var(--border);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ===== RESPONSIVE ===== */

@media (max-width: 1024px) {
  .about-inner {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    min-height: 55vh;
    padding-top: 8rem;
    padding-bottom: 3rem;
  }

  .hero-title {
    font-size: clamp(2.2rem, 8vw, 3.5rem);
  }

  .media-showcase-inner {
    grid-template-columns: 1fr 1fr;
    height: clamp(200px, 45vw, 360px);
  }

  .media-block:nth-child(3) {
    grid-column: 1 / -1;
    height: clamp(120px, 25vw, 200px);
  }

  .about {
    padding: 4rem var(--page-padding) 5rem;
  }

  .philosophy {
    padding-top: 8rem;
  }

  .clients-heading {
    padding-top: 8rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .contact-links {
    flex-direction: column;
    align-items: center;
    gap: 1.5rem;
  }

  .founder-letter {
    padding-top: 8rem;
  }

  .footer-inner {
    flex-direction: column;
    gap: 0.75rem;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .media-showcase-inner {
    grid-template-columns: 1fr;
    height: auto;
    gap: 0.5rem;
  }

  .media-block {
    height: 160px;
  }

  .media-block:nth-child(3) {
    grid-column: auto;
    height: 160px;
  }
}

