*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-secondary: #4A4A4A;
  --text-muted: #7A7A7A;
  --border: #D4CBC0;
  --terracotta: #C4755B;
  --sage: #8B9E7E;
  --sand: #D4C5A9;
