  cursor: pointer;
  transition: opacity 0.2s ease;
}

.nav-links a:hover {
  opacity: 0.55;
}

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 44px;
  height: 44px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 210;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background-color: var(--text);
  transition: transform 0.3s ease, opacity 0.3s ease;
