  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-heading h1 {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.clients-heading h1 span {
  font-weight: 400;
  font-style: italic;
  color: var(--text-muted);
  margin-left: 0.15em;
}

.clients-section {
  padding: 0 var(--page-padding) 8rem;
}

.clients-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2.5rem;
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: 0.65rem;
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-muted);
}

/* ===== CONTACT ===== */

.contact-hero {
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10rem var(--page-padding) 2rem;
  text-align: center;
}

.contact-title {
  font-family: var(--font-serif);
  font-size: clamp(5rem, 18vw, 16rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.04em;
}

.contact-links {
  display: flex;
  justify-content: center;
  gap: 3rem;
  padding: 0 var(--page-padding) 8rem;
}

.contact-links a {
  font-size: 1.0625rem;
  font-weight: 400;
  color: var(--text-secondary);
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.contact-links a:hover {
  opacity: 0.55;
}

