.footer {
  padding: 3rem var(--page-padding);
  border-top: 1px solid var(--border);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ===== RESPONSIVE ===== */

@media (max-width: 1024px) {
  .about-inner {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    min-height: 55vh;
    padding-top: 8rem;
    padding-bottom: 3rem;
  }

  .hero-title {
    font-size: clamp(2.2rem, 8vw, 3.5rem);
  }

  .media-showcase-inner {
    grid-template-columns: 1fr 1fr;
    height: clamp(200px, 45vw, 360px);
  }

  .media-block:nth-child(3) {
    grid-column: 1 / -1;
    height: clamp(120px, 25vw, 200px);
  }

  .about {
    padding: 4rem var(--page-padding) 5rem;
  }

  .philosophy {
    padding-top: 8rem;
  }

  .clients-heading {
    padding-top: 8rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .contact-links {
    flex-direction: column;
    align-items: center;
    gap: 1.5rem;
  }

  .founder-letter {
    padding-top: 8rem;
  }

  .footer-inner {
    flex-direction: column;
    gap: 0.75rem;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .media-showcase-inner {
    grid-template-columns: 1fr;
    height: auto;
    gap: 0.5rem;
  }

  .media-block {
    height: 160px;
  }

  .media-block:nth-child(3) {
    grid-column: auto;
    height: 160px;
  }
}

