  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: 3rem;
}

.philosophy-text {
  max-width: 680px;
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--text-secondary);
}

.philosophy-text p {
  margin-bottom: 1.5rem;
}

.section-divider {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--page-padding);
}

.section-divider hr {
  border: none;
  border-top: 1px solid var(--border);
}

.service-details {
  padding: 5rem var(--page-padding) 8rem;
}

.service-details-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.service-details-heading {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 4rem;
  max-width: 18ch;
  font-style: italic;
}

.service-item {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 3rem;
  margin-bottom: 3.5rem;
  padding-bottom: 3.5rem;
  border-bottom: 1px solid var(--border);
}

.service-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}

.service-name {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  padding-top: 0.25rem;
}

.service-description {
  font-size: 1.0625rem;
  line-height: 1.8;
  color: var(--text-secondary);
  max-width: 640px;
}

/* ===== CLIENTS ===== */

.clients-heading {
  padding: 12rem var(--page-padding) 4rem;
}

.clients-heading-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-heading h1 {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.clients-heading h1 span {
  font-weight: 400;
  font-style: italic;
  color: var(--text-muted);
  margin-left: 0.15em;
}

.clients-section {
  padding: 0 var(--page-padding) 8rem;
}

.clients-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem 2.5rem;
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: 0.65rem;
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-muted);
}

/* ===== CONTACT ===== */

.contact-hero {
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10rem var(--page-padding) 2rem;
  text-align: center;
}

.contact-title {
  font-family: var(--font-serif);
  font-size: clamp(5rem, 18vw, 16rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.04em;
}

.contact-links {
  display: flex;
  justify-content: center;
  gap: 3rem;
  padding: 0 var(--page-padding) 8rem;
}

.contact-links a {
  font-size: 1.0625rem;
  font-weight: 400;
  color: var(--text-secondary);
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.contact-links a:hover {
  opacity: 0.55;
}

/* ===== FOOTER ===== */

.footer {
  padding: 3rem var(--page-padding);
  border-top: 1px solid var(--border);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ===== RESPONSIVE ===== */

@media (max-width: 1024px) {
  .about-inner {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    min-height: 55vh;
    padding-top: 8rem;
    padding-bottom: 3rem;
  }

  .hero-title {
    font-size: clamp(2.2rem, 8vw, 3.5rem);
  }

  .media-showcase-inner {
    grid-template-columns: 1fr 1fr;
    height: clamp(200px, 45vw, 360px);
  }

  .media-block:nth-child(3) {
    grid-column: 1 / -1;
    height: clamp(120px, 25vw, 200px);
  }

  .about {
    padding: 4rem var(--page-padding) 5rem;
  }

  .philosophy {
    padding-top: 8rem;
  }

  .clients-heading {
    padding-top: 8rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .contact-links {
    flex-direction: column;
    align-items: center;
    gap: 1.5rem;
  }

  .founder-letter {
    padding-top: 8rem;
  }

  .footer-inner {
    flex-direction: column;
    gap: 0.75rem;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .media-showcase-inner {
    grid-template-columns: 1fr;
    height: auto;
    gap: 0.5rem;
  }

  .media-block {
    height: 160px;
  }

  .media-block:nth-child(3) {
    grid-column: auto;
    height: 160px;
  }
}
